# Check an image for unsafe or policy‑sensitive visual content using AWS Bedrock Guardrails\nimport os\n\n# Bedrock SDK for content safety (text & image)\nfrom boto3 import client as boto3_client\n\nclass ScoreImageSafety:\n    \"\"\"Flag unsafe visual content in an image using Amazon Bedrock Guardrails.\n    \"\"\"\n    @staticmethod\n    def is_safe(image_path: str) -> bool:\n        \"\"\"Determine whether the image passes safety filters.\n        Args:\n            image_path (str): Path to the image file.\n        Returns:\n            bool: True if safe, False otherwise.\n        \"\"\"\n        # Instantiate the Bedrock runtime client – credentials are set via AWS_ACCESS_KEY_ID / AWS_SECRET_ACCESS_KEY\n        bedrock = boto3_client(\"bedrock-runtime\", region_name=\"us-east-1\")\n        # Call the safety API (image guardrails endpoint)\n        response = bedrock.post_content_moderation(\n            image=open(image_path, \"rb\").read(),\n            contentType=\"application/octet-stream\"\n        )\n        # The response includes a boolean \"safe\" flag (simplified for illustration)\n        safe = response.get(\"safe\", True)\n        return safe\n\n# Local helper utilities (loaded in VisionClient)\n# -----------------------------------------------------------------------------\n# Configuration loading and client helpers defined in vision_client.py (separate file)\n# -----------------------------------------------------------------------------
